if(PHP_SAPI!=='cli'||!in_array(wp_get_environment_type(),array('local','development'),true)){exit("Refusing production.\n");}
$n=0;$saved=array();foreach(array('snd_dataset','snd_overrides','snd_explore_catalogue','snd_settings') as $key){$saved[$key]=get_option($key,null);} $tokens=array();$owner=get_current_user_id();
function cat_ok($v,$label){global $n;$n++;if(!$v){throw new RuntimeException($label);}}
try{
 foreach(array('snd_dataset','snd_overrides','snd_explore_catalogue') as $key){delete_option($key);}SND_Explore::reset();wp_set_current_user(0);
