 $pool=SND_Data::pool('municipality');$source=json_decode(file_get_contents(__DIR__.'/fixtures/rzs-municipalities-2026.json'),true);$expected=array_column($source['units'],'id');$actual=array_keys($pool);sort($expected);sort($actual);cat_ok($expected===$actual && count($pool)===197,'Exactly one game unit for every RZS leaf code');cat_ok(count(array_unique(array_column($source['units'],'sors_code')))===197,'Independent official reference codes unique');
