 SND_I18n::force('sr');$nature=json_decode(file_get_contents(__DIR__.'/fixtures/catalogue-verification-2026.json'),true);foreach($nature['approved'] as $ref){$kind=strtok($ref['id'],'-');$t=SND_Explore::pool($kind)[$ref['id']]??null;cat_ok($t && $t['name']===$ref['name'] && $t['verification_source']===$ref['source'],'Independently checked identity '.$ref['id']);}
 cat_ok(count(SND_Explore::pool('river'))===63 && count(SND_Explore::targets('river'))===61,'Reviewed public rivers separate from complete daily fund');cat_ok(count(SND_Explore::pool('mountain'))===188,'All 188 names checked against PSS');cat_ok(!SND_Explore::approved_id('river-499443148'),'Agla is an editorial draft');cat_ok(SND_Game::RULESET===4,'Existing season and daily slots retained');
 cat_ok(count(SND_Catalogue::pool('river'))===61,'Knowledge list excludes identities without river facts');cat_ok(!isset(SND_Catalogue::pool('river')['river-36871926'])&&!isset(SND_Catalogue::pool('river')['river-142049998']),'Both empty Toplica records are absent from knowledge');cat_ok(count(SND_Catalogue::pool('mountain'))===188&&count(SND_Catalogue::pool('municipality'))===197,'Complete mountains and official municipalities retained');
 $raw=SND_Explore::data();$raw_by_id=array_column($raw['items'],null,'id');cat_ok(isset($raw_by_id['river-499443148'])&&$raw_by_id['river-499443148']['review_status']==='pending','Unverified record remains available to editors');
 // Simulate the actual frozen 4.0 daily catalogue: no data deletion or reset.
 $c=SND_Game::challenge('river','practice');$c['catalog']=array_filter($raw_by_id,function($t){return $t['kind']==='river';});$c['mode']='daily';$c['storage_key']='snd_catalogue_frozen_test';update_option($c['storage_key'],$c,false);$s=array('challenge'=>$c,'stage'=>'guess','guesses'=>array(),'hint'=>false,'solved'=>false,'answers'=>array(),'question_index'=>0,'revision'=>3,'owner'=>0,'game_id'=>bin2hex(random_bytes(16)),'recorded'=>false);$token=bin2hex(random_bytes(24));$tokens[]=$token;SND_Game::persist($token,$s);$loaded=SND_Game::load($token);$out=SND_Game::public_state($loaded);
 cat_ok(count($out['catalog'])===63&&!in_array('river-499443148',array_column($out['catalog'],'id'),true),'Previously frozen daily catalogue also hides drafts');$before=$loaded;$err=SND_Game::act($loaded,'guess','river-499443148');cat_ok(is_wp_error($err)&&$loaded===$before,'Draft guess consumes no attempt or revision');cat_ok(SND_Game::act($loaded,'guess',$c['target']['id'])===true&&$loaded['solved'],'Existing reviewed target remains solvable');cat_ok(get_option($c['storage_key'])===$c,'Frozen challenge untouched');
 $legacy_q=array('type'=>'explore_city_river','correct'=>'a','options'=>array(array('id'=>'a','label'=>'Dunav','value'=>'Dunav'),array('id'=>'b','label'=>'Agla','value'=>'Agla'),array('id'=>'c','label'=>'Sava','value'=>'Sava'),array('id'=>'d','label'=>'Drina','value'=>'Drina')));$c['kind']='city';$c['questions']=array($legacy_q);$c['mode']='practice';$s=$before;$s['challenge']=$c;SND_Game::persist($token,$s);$loaded=SND_Game::load($token);$q=SND_Game::question_for($loaded,0);cat_ok($q['correct']==='a'&&array_column($q['options'],'id')===array('a','b','c','d'),'Old question keeps answer identifiers');cat_ok(!in_array('Agla',array_column($q['options'],'label'),true)&&$q===SND_Explore::safe_decoys($legacy_q,$c['date'].':0'),'Unanswered legacy decoys are replaced deterministically');
 $legacy=$raw;foreach($legacy['items'] as &$t){unset($t['review_status'],$t['verification_source'],$t['reviewed_on'],$t['review_note']);}unset($t);update_option('snd_explore_catalogue',$legacy,false);SND_Explore::reset();cat_ok(count(SND_Explore::pool('river'))===63&&!SND_Explore::approved_id('river-499443148'),'Legacy administrator catalogue inherits audited identity policy');$valid=SND_Explore::validate($legacy);cat_ok(!is_wp_error($valid),'Legacy catalogue import still works');
 $bad=$raw;$bad['items'][0]['verification_source']='javascript:alert(1)';cat_ok(is_wp_error(SND_Explore::validate($bad)),'Verified identity requires HTTPS evidence');$custom=$legacy;$unknown=$custom['items'][0];$unknown['id']='city-unreviewed-test';$unknown['name']='Unreviewed settlement';$custom['items'][]=$unknown;update_option('snd_explore_catalogue',$custom,false);SND_Explore::reset();cat_ok(!SND_Explore::approved_id($unknown['id'])&&!isset(SND_Explore::pool('city')[$unknown['id']]),'Unreviewed administrator entries stay private');
 echo 'PASS: '.$n.' official municipal codes, population partitions, nature identities, review import and frozen-day assertions.'.PHP_EOL;
}finally{
 foreach($tokens as $token){delete_transient('snd_session_'.$token);}delete_option('snd_catalogue_frozen_test');foreach($saved as $key=>$value){if($value===null){delete_option($key);}else{update_option($key,$value,false);}}SND_Explore::reset();SND_Settings::reset();SND_I18n::force(null);wp_set_current_user($owner);
